<div class="page-head"><div><h1>Mis tickets</h1><p>Seguimiento de todas tus solicitudes de soporte.</p></div><a href="<?= url('portal/nuevo') ?>" class="btn btn-brand"><i class="bi bi-plus-lg me-1"></i>Nuevo ticket</a></div>
<div class="seg mb-3"><?php foreach (['' => 'Todos', 'abiertos' => 'En atención', 'resueltos' => 'Resueltos'] as $k => $v): ?><a class="<?= $est === $k ? 'on' : '' ?>" href="<?= url('portal/tickets' . ($k ? "?estado=$k" : '')) ?>"><?= $v ?></a><?php endforeach; ?></div>
<div class="card-ui"><div class="table-responsive"><table class="table-ui"><thead><tr><th>Ticket</th><th>Prioridad</th><th>Estado</th><th>Creado</th><th>Atención estimada</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $t): ?><tr><td class="cell-main"><a href="<?= url('portal/ticket/' . $t['id']) ?>"><b><?= e($t['codigo']) ?></b></a><small><?= e(mb_strimwidth($t['asunto'], 0, 60, '…')) ?></small></td><td><?= prio_pill($t['prioridad']) ?></td><td><?= estado_pill($t['estado']) ?></td><td class="small"><?= fdate($t['created_at'], 'd/m/Y H:i') ?></td><td class="small"><?= in_array($t['estado'], ['resuelto', 'cerrado']) ? '—' : fdate($t['fecha_limite'], 'd/m H:i') ?></td><td class="text-end"><a href="<?= url('portal/ticket/' . $t['id']) ?>" class="btn btn-soft btn-sm">Abrir</a></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="6" class="empty-row"><i class="bi bi-inbox"></i>No hay tickets.</td></tr><?php endif; ?></tbody></table></div></div>
